"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for an equalizer toggle. Pass `playing` to control it, or `defaultPlaying` to let it hold its own state. */
export type EqualizerToggleProps = Omit<ComponentPropsWithoutRef<"button">, "onChange"> & {
  playing?: boolean;
  defaultPlaying?: boolean;
  onPlayingChange?: (playing: boolean) => void;
};

// Each bar loops through its own levels at its own pace, so the four never
// line up and the group reads as sound, not as a metronome.
const BARS = [
  { levels: [0.35, 0.9, 0.5, 1, 0.35], duration: 1.1, still: 0.55, rest: 0.375 },
  { levels: [0.8, 0.4, 1, 0.55, 0.8], duration: 0.9, still: 1, rest: 0.625 },
  { levels: [0.5, 1, 0.3, 0.75, 0.5], duration: 1.3, still: 0.4, rest: 0.375 },
  { levels: [1, 0.45, 0.7, 0.3, 1], duration: 1, still: 0.75, rest: 0.5 },
];
const SETTLE: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

/**
 * Plays or pauses a sound. While it plays, four bars move like an audio
 * level; paused, they rest as a low, still outline of the same bars. The children are the
 * button's name and must not change with the state, because `aria-pressed`
 * already says whether the sound plays.
 */
export function EqualizerToggle({
  playing,
  defaultPlaying = false,
  onPlayingChange,
  className,
  children,
  onClick,
  ...buttonProps
}: EqualizerToggleProps) {
  const [ownPlaying, setOwnPlaying] = useState(defaultPlaying);
  const on = playing ?? ownPlaying;
  const reduceMotion = useReducedMotion() ?? false;

  const toggle = () => {
    if (playing === undefined) setOwnPlaying(!on);
    onPlayingChange?.(!on);
  };

  return (
    <button
      {...buttonProps}
      type="button"
      aria-pressed={on}
      data-state={on ? "playing" : "paused"}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) toggle();
      }}
      className={cn(
        "inline-flex min-h-11 min-w-11 cursor-pointer touch-manipulation items-center justify-center gap-3 rounded-full border px-4 text-sm font-medium outline-none",
        "active:scale-97 motion-safe:transition motion-safe:duration-150",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50 disabled:active:scale-100",
        on
          ? "border-primary bg-primary text-primary-foreground"
          : "border-border bg-background text-foreground hover:bg-muted",
        className,
      )}
    >
      <span aria-hidden="true" className="flex h-4 items-end gap-0.5">
        {BARS.map((bar, index) => {
          const loops = on && !reduceMotion;
          // Reduced motion keeps the playing state as still bars of different heights.
          const level = on ? bar.still : bar.rest;
          return (
            <motion.span
              // The bars never reorder, so the index is a stable key.
              key={index}
              initial={false}
              animate={{ scaleY: loops ? bar.levels : level }}
              transition={
                loops
                  ? { duration: bar.duration, ease: "easeInOut", repeat: Infinity }
                  : reduceMotion
                    ? INSTANT
                    : SETTLE
              }
              className="block h-4 w-0.75 origin-bottom rounded-full bg-current"
            />
          );
        })}
      </span>
      {children}
    </button>
  );
}
